import unittest

from candidate import correct_bracketing

class TestCorrectBracketing(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(correct_bracketing(""))

    def test_single_open_bracket(self):
        self.assertFalse(correct_bracketing("("))

    def test_single_close_bracket(self):
        self.assertFalse(correct_bracketing(")"))

    def test_balanced_simple(self):
        self.assertTrue(correct_bracketing("()"))

    def test_balanced_nested(self):
        self.assertTrue(correct_bracketing("(()())"))

    def test_unbalanced_mismatch(self):
        self.assertFalse(correct_bracketing(")(()"))

    def test_unbalanced_extra_open(self):
        self.assertFalse(correct_bracketing("((()"))

    def test_unbalanced_extra_close(self):
        self.assertFalse(correct_bracketing(")()("))

    def test_long_balanced(self):
        self.assertTrue(correct_bracketing("((()))"))

    def test_long_unbalanced(self):
        self.assertFalse(correct_bracketing("((())))"))

    def test_mixed_case(self):
        self.assertTrue(correct_bracketing("()()()"))

    def test_non_bracket_characters(self):
        self.assertFalse(correct_bracketing("a(b)c"))

    def test_none_input(self):
        with self.assertRaises(TypeError):
            correct_bracketing(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            correct_bracketing(123)

    def test_very_long_balanced(self):
        brackets = "(" * 1000 + ")" * 1000
        self.assertTrue(correct_bracketing(brackets))

    def test_very_long_unbalanced(self):
        brackets = "(" * 1001 + ")" * 1000
        self.assertFalse(correct_bracketing(brackets))
